css:
/* by metanef */
.switch {
  transform: scale(2.5);
  /* Dimensions & Options */
  --container-width: 5em;
  --container-height: 2.4em;
  --width: 0.6em;
  --hover-width: 0.8em;
  --offset: 0.28em;
  --radius-btn: 9px;

  /* Color Tokens */
  --bg-light: #e8ecf2;
  --bg-dark: #1a1d24;
  --accent-light: #4f46e5;
  --accent-dark: #14b8a6;
  --icon-muted: #64748b;

  /* Shadows */
  --shadow-inset-light: inset 3px 3px 6px #c5cad3, inset -3px -3px 6px #ffffff;
  --shadow-inset-dark: inset 3px 3px 6px #121419, inset -3px -3px 6px #22262f;

  /* Durations */
  --transition-duration: 0.45s;
  --short-transition-duration: 0.2s;

  font-size: 14px;
  position: relative;
  display: inline-block;
  width: var(--container-width);
  height: var(--container-height);
}

/* Hide default HTML checkbox */
.switch .checkbox {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}

/* The slider track */
.slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background-color: var(--bg-light);
  box-shadow: var(--shadow-inset-light);
  transition:
    background-color var(--transition-duration),
    box-shadow var(--transition-duration);
  border-radius: var(--radius-btn);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 7px;
}

.slider .icon-sun,
.slider .icon-moon {
  width: 14px;
  height: 14px;
  pointer-events: none;
  z-index: 1;
  transition:
    opacity var(--transition-duration) ease-out,
    transform var(--transition-duration) ease-out,
    color var(--transition-duration) ease-out;
}

/* Light Mode: Sun hidden under handle on left, Moon visible on right */
.slider .icon-sun {
  color: var(--accent-light);
  opacity: 0;
  transform: scale(0);
}

.slider .icon-moon {
  color: var(--icon-muted);
  opacity: 0.85;
  transform: scale(1);
}

/* Dark Mode: Moon hidden under handle on right, Sun visible on left */
.checkbox:checked + .slider .icon-sun {
  color: var(--icon-muted);
  opacity: 0.85;
  transform: scale(1);
}

.checkbox:checked + .slider .icon-moon {
  color: var(--accent-dark);
  opacity: 0;
  transform: scale(0);
}

/* Handle element */
.slider::before {
  position: absolute;
  content: "";
  top: var(--offset);
  bottom: var(--offset);
  width: var(--width);
  border-radius: 5px;
  left: var(--offset);
  background-color: var(--accent-light);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.15);
  transition:
    transform var(--short-transition-duration),
    width var(--short-transition-duration),
    border-radius var(--short-transition-duration),
    background-color var(--short-transition-duration);
  z-index: 2;
}

/* Dark Mode State */
.checkbox:checked + .slider {
  background-color: var(--bg-dark);
  box-shadow: var(--shadow-inset-dark);
}

.checkbox:checked + .slider::before {
  background-color: var(--accent-dark);
  transform: translateX(
    calc(var(--container-width) - var(--offset) * 2 - var(--width))
  );
}

/* Hover effect: Light Mode handle stretches into right-facing D-shape */
.switch:hover .checkbox:not(:checked) + .slider::before {
  width: var(--hover-width);
  border-radius: 5px 50% 50% 5px;
}

/* Hover effect: Dark Mode handle stretches into left-facing D-shape */
.switch:hover .checkbox:checked + .slider::before {
  width: var(--hover-width);
  transform: translateX(
    calc(var(--container-width) - var(--offset) * 2 - var(--hover-width))
  );
  border-radius: 50% 5px 5px 50%;
}
